/** The blocks that run once per sounding note. */
class Voice {
 public:
  void prepare(double sampleRate, int maxBlock) {
    data.assign(static_cast<std::size_t>(5) * maxBlock, 0.0f);
    for (int i = 0; i < 5; i++) buf[i] = data.data() + i * maxBlock;
    dsp010.prepare(sampleRate, maxBlock);
    ch_dsp010_1[0] = buf[0]; io_dsp010[1] = ch_dsp010_1;
    dsp003.prepare(sampleRate, maxBlock);
    ch_dsp003_0[0] = buf[0]; io_dsp003[0] = ch_dsp003_0;
    ch_dsp003_1[0] = buf[1]; io_dsp003[1] = ch_dsp003_1;
    dsp022.prepare(sampleRate, maxBlock);
    ch_dsp022_0[0] = buf[2]; io_dsp022[0] = ch_dsp022_0;
    dsp024.prepare(sampleRate, maxBlock);
    ch_dsp024_0[0] = buf[1]; ch_dsp024_0[1] = buf[1]; io_dsp024[0] = ch_dsp024_0;
    ch_dsp024_1[0] = buf[2]; io_dsp024[1] = ch_dsp024_1;
    ch_dsp024_2[0] = buf[3]; ch_dsp024_2[1] = buf[4]; io_dsp024[2] = ch_dsp024_2;
  }

  void setParam(int index, double value) noexcept {
    switch (index) {
      case 0: dsp003.setParam(0, value); break;
      case 3: dsp003.setParam(3, value); break;
      case 4: dsp010.setParam(0, value); break;
      case 5: dsp010.setParam(1, value); break;
      case 8: dsp010.setParam(4, value); break;
      case 10: dsp010.setParam(6, value); break;
      case 11: dsp022.setParam(0, value); break;
      case 12: dsp022.setParam(1, value); break;
      case 13: dsp022.setParam(2, value); break;
      case 14: dsp022.setParam(3, value); break;
      case 15: dsp022.setParam(4, value); break;
      case 16: dsp022.setParam(5, value); break;
      case 17: dsp022.setParam(6, value); break;
      case 18: dsp022.setParam(7, value); break;
      case 19: dsp022.setParam(8, value); break;
      case 20: dsp022.setParam(9, value); break;
      case 21: dsp022.setParam(10, value); break;
      case 25: dsp024.setParam(0, value); break;
      case 26: dsp024.setParam(1, value); break;
      case 27: dsp024.setParam(2, value); break;
      default: (void)value; break;
    }
  }

  /** The note this voice now plays is the synth's `step`-th: each round robin (mod.voice-values) takes its value. */
  void setStep(long long step) noexcept {
    (void)step;
  }

  /** The unison copies (runtime.hpp, voice.unison): each oscillator that takes unison plays them. */
  void setUnison(int count, const double* cents, double gain) noexcept {
    dsp010.setUnison(count, cents, gain);
  }

  /** This voice's number (runtime.hpp): each seeded block (mod.random) draws its own sequence in every voice. */
  void setSeed(int voice) noexcept {
    (void)voice;
  }

  void noteOn(const VoiceNote& note) noexcept {
    dsp010.noteOn(dsp::adapter::Note{note.note, note.velocity, note.sounding});
    dsp003.noteOn(dsp::adapter::Note{note.note, note.velocity, note.sounding});
    if (!note.sounding) dsp022.reset();
    dsp022.noteOn(dsp::adapter::Note{note.note, note.velocity, note.sounding});
    dsp024.noteOn(dsp::adapter::Note{note.note, note.velocity, note.sounding});
  }

  void noteOff() noexcept {
    dsp010.noteOff();
    dsp003.noteOff();
    dsp022.noteOff();
    dsp024.noteOff();
  }

  /** A pressure message (0..127): channel pressure (poly false), or poly pressure for this voice's key (runtime.hpp). */
  void pressure(bool poly, double raw) noexcept {
    (void)poly;
    (void)raw;
  }

  bool finished() const noexcept { return dsp022.finished(); }

  /** Whether it has an envelope: one without is kept after its key, while Shared's and Global's envelopes release. */
  static constexpr bool OWN_ENVELOPE = true;

  void watch(float* out) const noexcept {
    out[0] = static_cast<float>(dsp022.stage());
    out[1] = static_cast<float>(dsp022.stageProgress());
  }

  /** Adds its outputs the filter pads show into the spectra (runtime.hpp Synth::block): each the mean of its channels. */
  void spectrum(float* const* out, int n) const noexcept {
    sumScaled(out[0], buf[1], 1.0f / 1, n);
  }

  double level() const noexcept { return lastLevel; }

  /** Writes its outputs Global reads into the taps (runtime.hpp calls it on the newest sounding voice). */
  void tap(float* const* taps, int n) const noexcept {
    (void)taps;
    (void)n;
  }

  void process(int n, double pitchHz, const VoiceRoutes& routes, float* const* shared, float* const* buses) noexcept {
    (void)pitchHz;
    (void)routes;
    (void)shared;
    {
      const int o = 0, m = n;
      dsp010.setInput(0, pitchHz);
      routes.mod.process(modSources, 0, routes.modBase, modOut);
      dsp010.setParam(3, modOut[2]);
      dsp010.setParam(5, modOut[3]);
      dsp010.setParam(2, modOut[4]);
      dsp010.process(dsp::adapter::Io{io_dsp010}, o, m);
      routes.mod.process(modSources, 0, routes.modBase, modOut);
      dsp003.setParam(1, modOut[0]);
      dsp003.setParam(2, modOut[1]);
      dsp003.process(dsp::adapter::Io{io_dsp003}, o, m);
      dsp022.process(dsp::adapter::Io{io_dsp022}, o, m);
      dsp024.process(dsp::adapter::Io{io_dsp024}, o, m);
    }
    double loudest = 0;
    sumInto(buses[0], buf[3], n); loudest = std::max(loudest, peak(buf[3], n));
    sumInto(buses[1], buf[4], n); loudest = std::max(loudest, peak(buf[4], n));
    lastLevel = loudest;
  }

 private:
  std::vector<float> data;
  float* buf[5] = {};
  dsp::adapter::OscWavetable dsp010;  // DSP010 osc.wavetable
  float* const* io_dsp010[2] = {};
  float* ch_dsp010_1[1] = {};
  dsp::adapter::FilterMorph dsp003;  // DSP003 filter.morph
  float* const* io_dsp003[2] = {};
  float* ch_dsp003_0[1] = {};
  float* ch_dsp003_1[1] = {};
  dsp::adapter::EnvEnvelope dsp022;  // DSP022 env.envelope
  float* const* io_dsp022[1] = {};
  float* ch_dsp022_0[1] = {};
  dsp::adapter::AmpVca dsp024;  // DSP024 amp.vca
  float* const* io_dsp024[3] = {};
  float* ch_dsp024_0[2] = {};
  float* ch_dsp024_1[1] = {};
  float* ch_dsp024_2[2] = {};
  float modOut[5] = {};
  float modSources[1] = {};
  double lastLevel = 0;
};

/** The blocks that run once, after the voices are summed into the buses. */
class Global {
 public:
  void prepare(double sampleRate, int maxBlock) {
    data.assign(static_cast<std::size_t>(10) * maxBlock, 0.0f);
    for (int i = 0; i < 10; i++) buf[i] = data.data() + i * maxBlock;
    dsp028.prepare(sampleRate, maxBlock);
    io_dsp028[0] = ch_dsp028_0;
    ch_dsp028_1[0] = buf[0]; ch_dsp028_1[1] = buf[1]; io_dsp028[1] = ch_dsp028_1;
    dsp023.prepare(sampleRate, maxBlock);
    ch_dsp023_0[0] = buf[0]; ch_dsp023_0[1] = buf[1]; io_dsp023[0] = ch_dsp023_0;
    ch_dsp023_2[0] = buf[2]; ch_dsp023_2[1] = buf[3]; io_dsp023[2] = ch_dsp023_2;
    dsp029.prepare(sampleRate, maxBlock);
    ch_dsp029_0[0] = buf[2]; ch_dsp029_0[1] = buf[3]; io_dsp029[0] = ch_dsp029_0;
    ch_dsp029_1[0] = buf[4]; ch_dsp029_1[1] = buf[5]; io_dsp029[1] = ch_dsp029_1;
    dsp030.prepare(sampleRate, maxBlock);
    ch_dsp030_0[0] = buf[2]; ch_dsp030_0[1] = buf[3]; io_dsp030[0] = ch_dsp030_0;
    ch_dsp030_1[0] = buf[6]; ch_dsp030_1[1] = buf[7]; io_dsp030[1] = ch_dsp030_1;
    dsp031.prepare(sampleRate, maxBlock);
    ch_dsp031_0[0] = buf[2]; ch_dsp031_0[1] = buf[3]; io_dsp031[0] = ch_dsp031_0;
    ch_dsp031_1[0] = buf[8]; ch_dsp031_1[1] = buf[9]; io_dsp031[1] = ch_dsp031_1;
    mod.prepare(sampleRate);
    mod.setTargetCount(1);
    mod.setTarget(0, 0, 1, sumState[0][0], sumState[0][1] >= 0.5 ? -1 : 1, sumState[0][2], 0);
    mod.setRouteCount(0, 8);
    setSlot(0, 0, slotState[0]);
    setSlot(0, 1, slotState[1]);
    setSlot(0, 2, slotState[2]);
    setSlot(0, 3, slotState[3]);
    setSlot(0, 4, slotState[4]);
    setSlot(0, 5, slotState[5]);
    setSlot(0, 6, slotState[6]);
    setSlot(0, 7, slotState[7]);
  }

  void setParam(int index, double value) noexcept {
    switch (index) {
      case 22: modBase[0] = static_cast<float>(value); break;
      case 23: dsp023.setParam(1, value); break;
      case 24: dsp023.setParam(2, value); break;
      case 28: dsp031.setParam(0, value); break;
      case 29: dsp031.setParam(1, value); break;
      case 30: dsp031.setParam(2, value); break;
      case 287: slotState[0][0] = value; setSlot(0, 0, slotState[0]); break;
      case 288: slotState[0][1] = value; setSlot(0, 0, slotState[0]); break;
      case 289: slotState[0][2] = value; setSlot(0, 0, slotState[0]); break;
      case 290: slotState[0][3] = value; setSlot(0, 0, slotState[0]); break;
      case 291: slotState[1][0] = value; setSlot(0, 1, slotState[1]); break;
      case 292: slotState[1][1] = value; setSlot(0, 1, slotState[1]); break;
      case 293: slotState[1][2] = value; setSlot(0, 1, slotState[1]); break;
      case 294: slotState[1][3] = value; setSlot(0, 1, slotState[1]); break;
      case 295: slotState[2][0] = value; setSlot(0, 2, slotState[2]); break;
      case 296: slotState[2][1] = value; setSlot(0, 2, slotState[2]); break;
      case 297: slotState[2][2] = value; setSlot(0, 2, slotState[2]); break;
      case 298: slotState[2][3] = value; setSlot(0, 2, slotState[2]); break;
      case 299: slotState[3][0] = value; setSlot(0, 3, slotState[3]); break;
      case 300: slotState[3][1] = value; setSlot(0, 3, slotState[3]); break;
      case 301: slotState[3][2] = value; setSlot(0, 3, slotState[3]); break;
      case 302: slotState[3][3] = value; setSlot(0, 3, slotState[3]); break;
      case 303: slotState[4][0] = value; setSlot(0, 4, slotState[4]); break;
      case 304: slotState[4][1] = value; setSlot(0, 4, slotState[4]); break;
      case 305: slotState[4][2] = value; setSlot(0, 4, slotState[4]); break;
      case 306: slotState[4][3] = value; setSlot(0, 4, slotState[4]); break;
      case 307: slotState[5][0] = value; setSlot(0, 5, slotState[5]); break;
      case 308: slotState[5][1] = value; setSlot(0, 5, slotState[5]); break;
      case 309: slotState[5][2] = value; setSlot(0, 5, slotState[5]); break;
      case 310: slotState[5][3] = value; setSlot(0, 5, slotState[5]); break;
      case 311: slotState[6][0] = value; setSlot(0, 6, slotState[6]); break;
      case 312: slotState[6][1] = value; setSlot(0, 6, slotState[6]); break;
      case 313: slotState[6][2] = value; setSlot(0, 6, slotState[6]); break;
      case 314: slotState[6][3] = value; setSlot(0, 6, slotState[6]); break;
      case 315: slotState[7][0] = value; setSlot(0, 7, slotState[7]); break;
      case 316: slotState[7][1] = value; setSlot(0, 7, slotState[7]); break;
      case 317: slotState[7][2] = value; setSlot(0, 7, slotState[7]); break;
      case 318: slotState[7][3] = value; setSlot(0, 7, slotState[7]); break;
      case 363: sumState[0][0] = value; mod.setTarget(0, 0, 1, sumState[0][0], sumState[0][1] >= 0.5 ? -1 : 1, sumState[0][2], 0); break;
      case 364: sumState[0][1] = value; mod.setTarget(0, 0, 1, sumState[0][0], sumState[0][1] >= 0.5 ? -1 : 1, sumState[0][2], 0); break;
      case 365: sumState[0][2] = value; mod.setTarget(0, 0, 1, sumState[0][0], sumState[0][1] >= 0.5 ? -1 : 1, sumState[0][2], 0); break;
      default: (void)value; break;
    }
  }

  void watch(float* out) const noexcept {
    (void)out;
  }

  /** Adds its outputs the filter pads show into the spectra (runtime.hpp Synth::block): each the mean of its channels. */
  void spectrum(float* const* out, int n) const noexcept {
    sumScaled(out[1], buf[6], 1.0f / 2, n);
    sumScaled(out[1], buf[7], 1.0f / 2, n);
    sumScaled(out[2], buf[4], 1.0f / 2, n);
    sumScaled(out[2], buf[5], 1.0f / 2, n);
    sumScaled(out[3], buf[0], 1.0f / 2, n);
    sumScaled(out[3], buf[1], 1.0f / 2, n);
  }

  /** Its envelopes, one for the whole instrument: runtime.hpp calls these on the keys (Voice allocation's Trigger). */
  void noteOn(const VoiceNote& note) noexcept {
    (void)note;
  }

  void noteOff() noexcept {

  }

  /** Whether its envelopes have finished: a voice with no envelope of its own rides their release (runtime.hpp). */
  bool finished() const noexcept { return true; }

  /** A note-on (channel 1..16) offered to its Ducks: true when one took it, so runtime.hpp plays no voice for it. */
  bool duck(int channel, int note) noexcept {
    (void)channel;
    (void)note;
    return false;
  }

  /** A mouse scroll of `travel` px (up positive), to its Mod wheels (mod.wheel). */
  void wheel(double travel) noexcept {
    (void)travel;
  }

  /** A MIDI mod wheel value (CC 1, 0..127), to its Mod wheels. */
  void modWheel(double raw) noexcept {
    (void)raw;
  }

  void process(int n, float* const* shared, float* const* taps, float* const* buses, float* left, float* right) noexcept {
    (void)shared;
    (void)taps;
    (void)buses;
    {
      const int o = 0, m = n;
      ch_dsp028_0[0] = buses[0]; ch_dsp028_0[1] = buses[1];
      dsp028.process(dsp::adapter::Io{io_dsp028}, o, m);
      mod.process(modSources, 0, modBase, modOut);
      dsp023.setParam(0, modOut[0]);
      dsp023.process(dsp::adapter::Io{io_dsp023}, o, m);
      dsp029.process(dsp::adapter::Io{io_dsp029}, o, m);
      dsp030.process(dsp::adapter::Io{io_dsp030}, o, m);
      dsp031.process(dsp::adapter::Io{io_dsp031}, o, m);
    }
    std::fill(left, left + n, 0.0f);
    std::fill(right, right + n, 0.0f);
    sumInto(left, buf[8], n);
    sumInto(right, buf[9], n);
  }

 private:
  std::vector<float> data;
  float* buf[10] = {};
  dsp::adapter::UtilTuner dsp028;  // DSP028 util.tuner
  float* const* io_dsp028[2] = {};
  float* ch_dsp028_0[2] = {};
  float* ch_dsp028_1[2] = {};
  dsp::adapter::AmpVca dsp023;  // DSP023 amp.vca
  float* const* io_dsp023[3] = {};
  float* ch_dsp023_0[2] = {};
  float* ch_dsp023_2[2] = {};
  dsp::adapter::UtilScope dsp029;  // DSP029 util.scope
  float* const* io_dsp029[2] = {};
  float* ch_dsp029_0[2] = {};
  float* ch_dsp029_1[2] = {};
  dsp::adapter::UtilScope dsp030;  // DSP030 util.scope
  float* const* io_dsp030[2] = {};
  float* ch_dsp030_0[2] = {};
  float* ch_dsp030_1[2] = {};
  dsp::adapter::FxLimiter dsp031;  // DSP031 fx.limiter
  float* const* io_dsp031[2] = {};
  float* ch_dsp031_0[2] = {};
  float* ch_dsp031_1[2] = {};
  dsp::ModRouting mod;
  float modBase[1] = {};
  float modOut[1] = {};
  float modSources[1] = {};
  double sumState[1][3] = {{1, 0, 1}};
  // Route slots: [source (an aux index, −1 none), on, polarity 0 + / 1 −, level], set by their params.
  double slotState[8][4] = {};
  static constexpr int AUX_SOURCE[1] = {-1};
  static constexpr int AUX_KIND[1] = {0};
  void setSlot(int t, int r, const double* slot) noexcept {
    const int g = static_cast<int>(std::lround(slot[0])), s = -1;
    (void)g;
    mod.setRoute(t, r, s, s >= 0 ? AUX_KIND[g] : 0, s >= 0 ? slot[1] : 0, slot[2] >= 0.5 ? 1 : 0, slot[3]);
  }
};

