  int next(int maxSamples, dsp::NoteSink& sink) noexcept {
    int n = maxSamples;
    if (left[0] <= 0) left[0] = seq_dsp014.advance(NOTE_IDLE, sink);
    n = std::min(n, left[0]);
    return n;
  }

  void rendered(int n) noexcept {
    for (int i = 0; i < 1; i++) left[i] -= n;
  }

